select 
from fixmedins_expert_info_d

    FIXMEDINS_CODE = #{fixmedinsCode}

       AND FIX_BLNG_ADMDVS = #{fixBlngAdmdvs}


        AND DR_NAME like concat(#{drName},"%")


        AND DR_CODE = #{drCode}


        AND CERTNO = #{certNo}


        AND DR_PRAC_SCP_CODE = #{drPracScpCode}


        AND AUDIT_STATUS = #{auditStatus}


        and DEPT_MAJOR = #{deptMajor}


        and ASSIGN_FLAG = #{assignFlag}


        and VALI_FLAG = #{valiFlag}


